import java.io.*;

class Solution {
    public int isPrefixOfWord(String sentence, String searchWord) {
        int m = searchWord.length();
        int wordIndex = 1;
        int i = 0;

        while (i < sentence.length()) {
            int j = i;
            while (j < sentence.length() && sentence.charAt(j) != ' ') {
                j++;
            }

            if (j - i >= m && sentence.regionMatches(i, searchWord, 0, m)) {
                return wordIndex;
            }

            wordIndex++;
            i = j + 1;
        }

        return -1;
    }
}

