int isPrefixOfWord(const char *sentence, const char *searchWord) {
    int m = (int)strlen(searchWord);
    int wordIndex = 1;
    int i = 0;
    int n = (int)strlen(sentence);

    while (i < n) {
        int j = i;
        while (j < n && sentence[j] != ' ') {
            ++j;
        }

        if (j - i >= m && strncmp(sentence + i, searchWord, (size_t)m) == 0) {
            return wordIndex;
        }

        ++wordIndex;
        i = j + 1;
    }

    return -1;
}

