                if (inString) {
                    if (found < 2) {
                        result[found++] = current.toString();
                    }
                    current.setLength(0);
                    inString = false;
                } else {
                    inString = true;
                }
            } else if (inString) {
                current.append(c);
            }
        }
        return result;
    }

    public static void main(String[] args) throws Exception {
